76-  if (claim.due !== null) return claim.due;
77-  const halfUp = roundsHalfUp(claim, late);
78-  const figure = claim.stated && claim.status !== 'PENDING' ? (claim.statedDue ?? 'n/a') : due(claim.amount, rate, floor(claim.date), halfUp);
79-  if (late === undefined || figure === 'n/a') return figure;
80-  const steps = lateSteps(claim, late);
81-  return steps === 0 ? figure : shown(hundredths(figure) + percentOf(figure, late.pct(claim.date), steps, halfUp));
82-}
